<?php
// Admin order, shipping, cancellation, and return lists.

    $filters=['konfirmasi'=>"o.status IN ('Belum Bayar','Menunggu Konfirmasi')",'diproses'=>"o.status IN ('Diproses','Dikirim')",'selesai'=>"o.status IN ('Selesai','Selesai Belum Dinilai')",'batal'=>"o.status='Dibatalkan'",'refund'=>"EXISTS (SELECT 1 FROM tb_refund r WHERE r.id_orders=o.id_orders)"];
    $orders=query('SELECT o.*,u.nama,u.alamat,u.telp,j.nama_jasa,j.harga_jasa,m.nama_metode,m.harga_admin FROM orders o JOIN tb_user u ON u.id_user=o.id_user JOIN jasa_kirim j ON j.id_jasa=o.id_jasa JOIN metode m ON m.id_metode=o.id_metode WHERE '.$filters[$route].' ORDER BY o.id_orders DESC');
    if(!$orders) empty_state('Semua sudah tertangani.','Belum ada pesanan pada daftar ini.','bangjanganbang/index.php','Kembali ke ringkasan');
    foreach($orders as $order): $details=order_details($order['id_orders']); $total=array_sum(array_map(function($d){return $d['harga_satuan']*$d['qty'];},$details))+$order['harga_jasa']+$order['harga_admin']; ?>
    <article class="panel order-card"><div class="order-heading"><div><strong>#TM-<?= (int)$order['id_orders'] ?></strong><span class="muted"> · <?= e($order['tanggal']) ?></span></div><?= status_badge($order['status']) ?></div><div class="admin-order-grid"><div><?php foreach($details as $item): ?><div class="mini-product"><img src="<?= e(url($item['img'])) ?>" alt=""><div><strong><?= e($item['nama_barang']) ?></strong><small><?= (int)$item['qty'] ?> × <?= rupiah($item['harga_satuan']) ?></small></div></div><?php endforeach; ?></div><div class="order-recipient"><span class="eyebrow">PENERIMA</span><strong><?= e($order['nama']) ?></strong><p><?= e($order['alamat']) ?><br><?= e($order['telp']) ?></p><small><?= e($order['nama_jasa'].' · '.$order['nama_metode']) ?></small><p><strong>Total <?= rupiah($total) ?></strong></p><?php if($order['pesan']): ?><p class="muted">Catatan: <?= e($order['pesan']) ?></p><?php endif; ?></div></div>
    <?php if($route==='refund'): $refunds=query('SELECT * FROM tb_refund WHERE id_orders=? ORDER BY id_refund DESC',[(int)$order['id_orders']]); foreach($refunds as $refund): ?><div class="notice info"><strong>Pengajuan retur</strong> · <?= status_badge($refund['status_refund']) ?><p><?= e($refund['alasan']) ?></p><a class="text-link" href="<?= e(url($refund['bukti'])) ?>" target="_blank" rel="noopener">Lihat foto bukti <?= icon('arrow') ?></a></div><?php endforeach; endif; ?>
    <div class="order-actions"><?php if($order['bukti_pembayaran']): ?><a class="button small secondary" target="_blank" rel="noopener" href="<?= e(url($order['bukti_pembayaran'])) ?>">Lihat bukti pembayaran</a><?php endif;
    if($order['status']==='Menunggu Konfirmasi') action_form('confirm',$order['id_orders'],'Konfirmasi pembayaran');
    if(in_array($order['status'],['Belum Bayar','Menunggu Konfirmasi'])) action_form('cancel',$order['id_orders'],'Batalkan','button small ghost','Batalkan pesanan dan kembalikan stok?');
    if($order['status']==='Diproses') action_form('ship',$order['id_orders'],'Tandai sudah dikirim');
    if($route==='refund' && $order['status']==='Diajukan Retur') { action_form('accept_refund',$order['id_orders'],'Terima retur','button small','Terima pengajuan retur ini?'); action_form('reject_refund',$order['id_orders'],'Tolak retur','button small ghost','Tolak pengajuan retur ini?'); }
    ?></div></article><?php endforeach;
